const { World, setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

class TodoWorld extends World {
  constructor(options) {
    super(options);
    this.window = null;
    this.document = null;
  }

  setupDom() {
    this.window = new Window({ url: 'http://localhost/' });
    this.document = this.window.document;
    const htmlPath = path.resolve(__dirname, '../../js/index.html');
    const html = fs.readFileSync(htmlPath, 'utf8');
    const bodyMatch = html.match(/<body>([\s\S]*)<\/body>/);
    this.document.body.innerHTML = bodyMatch[1];
    const scriptPath = path.resolve(__dirname, '../../js/app.js');
    const script = fs.readFileSync(scriptPath, 'utf8');
    this.window.eval(script);
    this.window.localStorage.clear();
  }

  getTodoItems() {
    return Array.from(this.document.querySelectorAll('.todo-list li'));
  }

  findTodoByTitle(title) {
    return this.getTodoItems().find(li => {
      const label = li.querySelector('.view label');
      return label && label.textContent === title;
    });
  }

  addTodo(title) {
    if (!this.window) this.setupDom();
    const input = this.document.querySelector('.new-todo');
    input.value = title;
    input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
  }

  markTodoComplete(title) {
    const li = this.findTodoByTitle(title);
    if (li) {
      const checkbox = li.querySelector('.toggle');
      if (!checkbox.checked) {
        checkbox.click();
      }
    }
  }

  editTodo(title) {
    const li = this.findTodoByTitle(title);
    if (li) {
      const label = li.querySelector('.view label');
      label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
    }
  }

  navigateTo(filter) {
    if (!this.window) this.setupDom();
    this.window.location.hash = filter;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  reload() {
    const stored = this.window.localStorage.getItem('todomvc-shakedown');
    const hash = this.window.location.hash;
    this.setupDom();
    if (stored) {
      this.window.localStorage.setItem('todomvc-shakedown', stored);
    }
    if (hash) {
      this.window.location.hash = hash;
    }
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }
}

setWorldConstructor(TodoWorld);

