(function () {
  'use strict';

  var STORAGE_KEY = 'todomvc-shakedown';
  var newTodoInput = document.querySelector('.new-todo');
  var todoList = document.querySelector('.todo-list');
  var mainSection = document.querySelector('.main');
  var footerSection = document.querySelector('.footer');
  var todoCount = document.querySelector('.todo-count');
  var toggleAllCheckbox = document.querySelector('.toggle-all');
  var clearCompletedBtn = document.querySelector('.clear-completed');
  var filterLinks = document.querySelectorAll('.filters a');

  function loadTodos() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (e) {
      return [];
    }
  }

  function saveTodos(todos) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2);
  }

  function getFilter() {
    var hash = window.location.hash || '#/';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  /** @planks("the new todo input is focused") @planks("the counter shows {string}") @planks("the {string} section is hidden") @planks("the {string} section is visible") */
  function render() {
    var todos = loadTodos();
    var filter = getFilter();
    todoList.innerHTML = '';

    var filtered = todos.filter(function (todo) {
      if (filter === 'active') return !todo.completed;
      if (filter === 'completed') return todo.completed;
      return true;
    });

    filtered.forEach(function (todo) {
      var li = document.createElement('li');
      li.dataset.id = todo.id;
      if (todo.completed) li.classList.add('completed');

      var div = document.createElement('div');
      div.className = 'view';

      var checkbox = document.createElement('input');
      checkbox.className = 'toggle';
      checkbox.type = 'checkbox';
      checkbox.checked = todo.completed;

      var label = document.createElement('label');
      label.textContent = todo.title;

      var destroyBtn = document.createElement('button');
      destroyBtn.className = 'destroy';

      div.appendChild(checkbox);
      div.appendChild(label);
      div.appendChild(destroyBtn);

      var editInput = document.createElement('input');
      editInput.className = 'edit';
      editInput.value = todo.title;

      li.appendChild(div);
      li.appendChild(editInput);
      todoList.appendChild(li);
    });

    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var completedCount = todos.filter(function (t) { return t.completed; }).length;
    var totalCount = todos.length;

    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' +
      (activeCount === 1 ? 'item left' : 'items left');

    if (totalCount === 0) {
      mainSection.style.display = 'none';
      footerSection.style.display = 'none';
    } else {
      mainSection.style.display = '';
      footerSection.style.display = '';
    }

    toggleAllCheckbox.checked = totalCount > 0 && activeCount === 0;
    clearCompletedBtn.style.display = completedCount > 0 ? '' : 'none';

    filterLinks.forEach(function (link) {
      link.classList.remove('selected');
      var linkFilter = link.getAttribute('href');
      if (linkFilter === '#/' && filter === 'all') link.classList.add('selected');
      if (linkFilter === '#/active' && filter === 'active') link.classList.add('selected');
      if (linkFilter === '#/completed' && filter === 'completed') link.classList.add('completed');
      if (linkFilter === '#/active' && filter === 'active') link.classList.add('selected');
    });
  }

  /** @planks("I add a todo {string}") */
  function addTodo(title) {
    var trimmed = title.trim();
    if (!trimmed) return;
    var todos = loadTodos();
    todos.push({ id: generateId(), title: trimmed, completed: false });
    saveTodos(todos);
    render();
  }

  /** @planks("I click the checkbox for todo {string}") */
  function toggleTodo(id) {
    var todos = loadTodos();
    todos = todos.map(function (t) {
      if (t.id === id) return { id: t.id, title: t.title, completed: !t.completed };
      return t;
    });
    saveTodos(todos);
    render();
  }

  /** @planks("I check the toggle-all checkbox") */
  function toggleAll() {
    var todos = loadTodos();
    var allCompleted = todos.every(function (t) { return t.completed; });
    todos = todos.map(function (t) {
      return { id: t.id, title: t.title, completed: !allCompleted };
    });
    saveTodos(todos);
    render();
  }

  /** @planks("I click the clear completed button") */
  function clearCompleted() {
    var todos = loadTodos();
    todos = todos.filter(function (t) { return !t.completed; });
    saveTodos(todos);
    render();
  }

  /** @planks("the destroy button for todo {string} is visible") */
  function destroyTodo(id) {
    var todos = loadTodos();
    todos = todos.filter(function (t) { return t.id !== id; });
    saveTodos(todos);
    render();
  }

  /** @planks("Editing saves on Enter") @planks("Editing saves on blur") @planks("Edit input is trimmed") */
  function saveEdit(id, newTitle) {
    var trimmed = newTitle.trim();
    var todos = loadTodos();
    if (!trimmed) {
      todos = todos.filter(function (t) { return t.id !== id; });
    } else {
      todos = todos.map(function (t) {
        if (t.id === id) return { id: t.id, title: trimmed, completed: t.completed };
        return t;
      });
    }
    saveTodos(todos);
    render();
  }

  /** @planks("Escape cancels edit") */
  function cancelEdit(li) {
    li.classList.remove('editing');
    var editInput = li.querySelector('.edit');
    var todoId = li.dataset.id;
    var todos = loadTodos();
    var todo = todos.find(function (t) { return t.id === todoId; });
    if (todo) editInput.value = todo.title;
  }

  // Event: new todo input
  newTodoInput.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') {
      addTodo(newTodoInput.value);
      newTodoInput.value = '';
    }
  });

  // Events: todo list (delegated)
  todoList.addEventListener('click', function (e) {
    var li = e.target.closest('li');
    if (!li) return;
    var id = li.dataset.id;

    if (e.target.classList.contains('toggle')) {
      toggleTodo(id);
    } else if (e.target.classList.contains('destroy')) {
      destroyTodo(id);
    }
  });

  todoList.addEventListener('dblclick', function (e) {
    if (e.target.tagName === 'LABEL') {
      var li = e.target.closest('li');
      li.classList.add('editing');
      var editInput = li.querySelector('.edit');
      editInput.focus();
    }
  });

  todoList.addEventListener('keydown', function (e) {
    if (e.target.classList.contains('edit')) {
      var li = e.target.closest('li');
      var id = li.dataset.id;
      if (e.key === 'Enter') {
        saveEdit(id, e.target.value);
      } else if (e.key === 'Escape') {
        cancelEdit(li);
      }
    }
  });

  todoList.addEventListener('blur', function (e) {
    if (e.target.classList.contains('edit')) {
      var li = e.target.closest('li');
      if (li && li.classList.contains('editing')) {
        saveEdit(li.dataset.id, e.target.value);
      }
    }
  }, true);

  // Event: toggle all
  toggleAllCheckbox.addEventListener('change', function () {
    toggleAll();
  });

  // Event: clear completed
  clearCompletedBtn.addEventListener('click', function () {
    clearCompleted();
  });

  // Event: filter links
  filterLinks.forEach(function (link) {
    link.addEventListener('click', function () {
      render();
    });
  });

  // Listen for hash changes
  window.addEventListener('hashchange', render);

  // Initial render
  render();
})();

